// Synthetic state-machine lab. No HTTP requests, persistent storage or real external actions.
const results=[];
function check(name, expected, observed){results.push({case:name,expected,observed,pass:JSON.stringify(expected)===JSON.stringify(observed)});}
function receiver(){const seen=new Set();let actions=0;let version=0;return {handle(e){if(!e||typeof e.id!=='string'||!e.id.trim()||!Number.isInteger(e.version))return 'reject';if(seen.has(e.id))return 'duplicate';if(e.version<=version){seen.add(e.id);return 'stale';}seen.add(e.id);actions++;version=e.version;return 'applied';}, stats(){return {actions,version};}};}
let r=receiver();check('valid event','applied',r.handle({id:'a',version:1}));check('sequential duplicate','duplicate',r.handle({id:'a',version:1}));check('one action for replay',1,r.stats().actions);check('newer event','applied',r.handle({id:'b',version:3}));check('older event arrives last','stale',r.handle({id:'c',version:2}));check('no state regression',3,r.stats().version);check('missing event ID','reject',r.handle({version:4}));check('malformed version','reject',r.handle({id:'d',version:'4'}));
function retry(status,attempt,seconds){if(attempt>=3)return {decision:'stop'};if(status===429)return {decision:'retry',waitSeconds:Math.max(1,seconds||2)};if(status===503)return {decision:'retry',waitSeconds:2**attempt};return {decision:'review'};}
check('429 provider wait',{decision:'retry',waitSeconds:30},retry(429,1,30));check('503 bounded backoff',{decision:'retry',waitSeconds:4},retry(503,2));check('retry budget exhausted',{decision:'stop'},retry(503,3));check('ambiguous timeout is reviewed',{decision:'review'},retry(0,1));
// Controlled interleaving, NOT simultaneous n8n executions or database testing.
const unsafeSeen=new Set();let unsafeActions=0;const aSaw=unsafeSeen.has('race'),bSaw=unsafeSeen.has('race');if(!aSaw){unsafeActions++;unsafeSeen.add('race');}if(!bSaw){unsafeActions++;unsafeSeen.add('race');}check('lookup then write race demonstrates two actions',2,unsafeActions);
let externalActions=0;const completed=new Set();function unsafeReplay(){if(completed.has('crash'))return;externalActions++;/* crash before marking complete */}unsafeReplay();unsafeReplay();check('crash gap demonstrates duplicate external action',2,externalActions);
const providerKeys=new Set();let keyedActions=0;function mockProvider(key){if(providerKeys.has(key))return 'replayed';providerKeys.add(key);keyedActions++;return 'created';}mockProvider('order-1');mockProvider('order-1');check('mock provider idempotency prevents second action',1,keyedActions);
return [{json:{scope:'Synthetic in-memory state-machine fixtures, not end-to-end webhook validation',cases:results.length,passed:results.filter(x=>x.pass).length,failed:results.filter(x=>!x.pass).length,results}}];
